SET @xml = CAST('<root>' AS xml);

OPEN xml_cursor CURSOR FOR
    SELECT @xml.query('for $i in tabi[1 to string-length(//records)] 
                        return <record>{sql:column($i+1)}</record>')
AS tabi(i) FOR XML PATH(''), TYPE;

INSERT INTO #temp ( Column1, Column2)
