#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  // Set GPIO pin 12 as an output
  gpioSetup(12, PI_OUTPUT);

  // Set the initial value of the output pin to LOW (0V)
  gpioWrite(12, PI_LOW);

